const int IN1 = 7, IN2 = 8, ENA = 9;    // left motor
const int IN3 = 5, IN4 = 4, ENB = 6;    // right motor

void setupMotors() {
  int pins[] = {IN1, IN2, ENA, IN3, IN4, ENB};
  for (int p : pins) pinMode(p, OUTPUT);
}

void driveMotor(int in1, int in2, int en, int speed) {
  bool fwd = speed >= 0;
  digitalWrite(in1, fwd ? HIGH : LOW);
  digitalWrite(in2, fwd ? LOW : HIGH);
  analogWrite(en, constrain(abs(speed), 0, 255));
}

void drive(int left, int right) {
  driveMotor(IN1, IN2, ENA, left);
  driveMotor(IN3, IN4, ENB, right);
}

void loop() {
  drive(180, 180);  delay(1000);  // forward
  drive(0, 0);      delay(400);   // stop
  drive(-180, -180); delay(1000); // reverse
  drive(0, 0);      delay(400);
  drive(180, -180); delay(800);   // spin in place
  drive(0, 0);      delay(1000);
}

