int THRESHOLD = 500;  // set from your measured black/white midpoint

bool overLine(int pin) {
  // black absorbs IR -> higher analog reading on most modules
  return analogRead(pin) > THRESHOLD;
}

const int BASE = 150;   // straight-ahead speed

void loop() {
  bool l = overLine(SENS_L);
  bool r = overLine(SENS_R);
  if (l && r)       drive(BASE, BASE);      // centred: straight
  else if (l && !r) drive(0, BASE);         // drifted right: turn left
  else if (!l && r) drive(BASE, 0);         // drifted left: turn right
  else              drive(BASE, BASE);      // both off: keep going
}

void setup() {
  Serial.begin(9600);
  setupMotors();
  pinMode(SENS_L, INPUT);
  pinMode(SENS_R, INPUT);
  delay(2000);   // time to set the robot on the line
}

int lineError() {
  int l = analogRead(SENS_L);
  int r = analogRead(SENS_R);
  return l - r;   // 0 when balanced over the line; sign shows drift direction
}

float Kp = 0.15;   // start small; tune upward

void loop() {
  int error = lineError();
  int turn = (int)(Kp * error);
  int left  = constrain(BASE - turn, 0, 255);
  int right = constrain(BASE + turn, 0, 255);
  drive(left, right);
}

int lastError = 0;

void loop() {
  bool l = overLine(SENS_L), r = overLine(SENS_R);
  int error = lineError();
  if (!l && !r) {                 // line lost: search toward last-seen side
    if (lastError > 0) drive(0, BASE);      // was drifting one way -> turn back
    else               drive(BASE, 0);
    return;
  }
  lastError = error;
  int turn = (int)(Kp * error);
  drive(constrain(BASE - turn, 0, 255), constrain(BASE + turn, 0, 255));
}

const int LED = 13;
unsigned long lastBlink = 0;
bool ledOn = false;

void heartbeat() {
  if (millis() - lastBlink >= 250) {
    ledOn = !ledOn;
    digitalWrite(LED, ledOn);
    lastBlink = millis();
  }
}
